contracts/utils/Faucet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.6;

import "@openzeppelin/contracts/access/AccessControl.sol";

contract Faucet is AccessControl {
    event Faucet(address indexed to, uint256 indexed eventId, uint256 indexed chainId, uint256 amount);

    constructor(address[] memory admins) payable {
        for (uint i = 0; i < admins.length; i++)
            _setupRole(DEFAULT_ADMIN_ROLE, admins[i]);
    }

    function faucet(address toAddress, uint256 eventId, uint256 chainId, uint256 amount) public onlyRole(DEFAULT_ADMIN_ROLE) {
        withdraw(toAddress, amount);
        emit Faucet(toAddress, eventId, chainId, amount);
    }

    function withdraw(address toAddress, uint256 amount) public onlyRole(DEFAULT_ADMIN_ROLE) {
        require(address(this).balance >= amount, "not enough funds");
        (bool sent, ) = payable(toAddress).call{value: amount}("");
        require(sent, "Transfer failed");
    }

    receive() external payable {}


}

contracts/tokens/BridgeERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.6;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract BridgeERC20 is ERC20, Ownable {
    address public bridgeAddress; // address of bridge contract on this network

    uint8 _decimals;

    constructor(string memory name_, string memory symbol_, uint8 decimals_, address bridgeAddress_)
    ERC20(name_, symbol_)
    Ownable() {
        bridgeAddress = bridgeAddress_;
        _decimals = decimals_;
    }

    function decimals() public view override returns (uint8) {
        return _decimals;
    }

    function setBridgeAddress(address bridgeAddress_) public onlyOwner() {
        bridgeAddress = bridgeAddress_;
    }

    function _transfer(
        address sender,
        address recipient,
        uint amount
    ) internal virtual override {
        if (sender == bridgeAddress) {
            // user transfer tokens to ambrosus => need to mint it
            _mint(recipient, amount);
        } else if (recipient == bridgeAddress) {
            // user withdraw tokens from ambrosus => need to burn it
            _burn(sender, amount);
        } else {
            super._transfer(sender, recipient, amount);
        }
    }
}

